#endif
static inline void fc3_widen(const int8_t *restrict in) {
    for (int i = 0; i < 64; i++) fc3_a16[i] = in[i];
}
// fc3_rows: n rows of weights starting at w. 4 rows at a time: each activation pair is loaded once and
// feeds all 4 rows (CMSIS-NN's vec_mat_mult does the same with 2 rows; our activations are already int16).
__attribute__((always_inline)) static inline void fc3_rows(const uint32_t *restrict w, int32_t *restrict out, int n) {
    int o = 0;
    for (; o + 3 < n; o += 4) {
        const int16_t *a = fc3_a16;
        int32_t s0 = 0, s1 = 0, s2 = 0, s3 = 0;
        #pragma GCC unroll 1
        for (int j = 0; j < 16; j++) {
            uint32_t a01, a23;
            memcpy(&a01, a + 4 * j, 4);
            memcpy(&a23, a + 4 * j + 2, 4);
            { uint32_t x = w[0 + j];
              s0 = SMLAD(SXTB16(x), a01, s0);
              s0 = SMLAD(SXTB16_ROR8(x), a23, s0); }
            { uint32_t x = w[16 + j];
              s1 = SMLAD(SXTB16(x), a01, s1);
              s1 = SMLAD(SXTB16_ROR8(x), a23, s1); }
            { uint32_t x = w[32 + j];
              s2 = SMLAD(SXTB16(x), a01, s2);
              s2 = SMLAD(SXTB16_ROR8(x), a23, s2); }
            { uint32_t x = w[48 + j];
              s3 = SMLAD(SXTB16(x), a01, s3);
              s3 = SMLAD(SXTB16_ROR8(x), a23, s3); }
        }
        out[o + 0] = s0;
        out[o + 1] = s1;
        out[o + 2] = s2;
        out[o + 3] = s3;
        w += 4 * 16;
    }
    const int left = (n - o) & 3;                           // leftover rows (< 4), one at a time
    for (int r = 0; r < left; r++, o++) {
        const int16_t *a = fc3_a16;
        int32_t s0 = 0;
        for (int j = 0; j < 16; j++) {
            uint32_t x = w[j], a01, a23;
            memcpy(&a01, a + 4 * j, 4);
            memcpy(&a23, a + 4 * j + 2, 4);
            s0 = SMLAD(SXTB16(x), a01, s0);
            s0 = SMLAD(SXTB16_ROR8(x), a23, s0);
        }
        out[o] = s0;
        w += 16;
    }
}
__attribute__((noinline)) static void MAFC_IN_SRAM(fc3)(const int8_t *restrict in, int32_t *restrict out) {
    (void)in;
#if defined(PICO_ON_DEVICE) && PICO_ON_DEVICE
    const uintptr_t wa = (uintptr_t)fc3_w;
    if (wa >= XIP_BASE && wa < XIP_NOCACHE_NOALLOC_BASE) {       // weights in flash: stream them
        static int ch = -1;
        if (ch < 0) ch = dma_claim_unused_channel(true);
        xip_ctrl_hw->stream_ctr = 0;
        while (!(xip_ctrl_hw->stat & XIP_STAT_FIFO_EMPTY_BITS)) (void)xip_aux_hw->stream;
        xip_ctrl_hw->stream_addr = (uint32_t)wa;
        xip_ctrl_hw->stream_ctr = 160;
        dma_channel_config c = dma_channel_get_default_config(ch);
        channel_config_set_transfer_data_size(&c, DMA_SIZE_32);
        channel_config_set_read_increment(&c, false);
        channel_config_set_write_increment(&c, true);
        channel_config_set_dreq(&c, DREQ_XIP_STREAM);
        const void *src = (const void *)&xip_aux_hw->stream;
        dma_channel_configure(ch, &c, fc3_sbuf[0], src, 128, true);
        for (int b = 0; b < 2; b++) {
            const int r0 = b * 8, nr = 10 - r0 < 8 ? 10 - r0 : 8;
            dma_channel_wait_for_finish_blocking(ch);
            if (b + 1 < 2) {
                const int r1 = r0 + 8, nr1 = 10 - r1 < 8 ? 10 - r1 : 8;
                dma_channel_configure(ch, &c, fc3_sbuf[(b + 1) & 1], src, nr1 * 16, true);
            }
            fc3_rows(fc3_sbuf[b & 1], out + r0, nr);
        }
        return;
    }
    fc3_rows(fc3_w, out, 10);                          // weights in SRAM: read them directly
#else
    for (int b = 0; b < 2; b++) {                          // PC: the same blocks, memcpy as the DMA
        const int r0 = b * 8, nr = 10 - r0 < 8 ? 10 - r0 : 8;
        memcpy(fc3_sbuf[b & 1], fc3_w + r0 * 16, (size_t)nr * 16 * 4);
        fc3_rows(fc3_sbuf[b & 1], out + r0, nr);
    }
#endif
}

uint32_t ref_infer(const int8_t img[REF_IMG_PIXELS], int32_t logits[REF_N_CLASSES]) {
    PROF_BEGIN();
    widen_img(img);   // counted in the conv1 stage
    for (int c = 0; c < 80; c++) {
        conv1_ch(img16, conv1_kp + 6 * c, ch16_a);
        PROF_STAGE(0);
        dw1_ch(ch16_a, dw1_kp + 6 * c, ch16_b);
        PROF_STAGE(1);
        pool1_ch(ch16_b, ch16_a);
        PROF_STAGE(2);
        dw2_ch(ch16_a, dw2_kp + 6 * c, ch_a);
        PROF_STAGE(3);
        pool2_ch(ch_a, feat + 4 * c);
        PROF_STAGE(4);
    }
    norm0(feat, act);
    fc1_widen(act);
    fc1(act, acc);
    PROF_STAGE(5);
    norm1(acc, act);
    fc2_widen(act);
    fc2(act, acc);
    PROF_STAGE(6);
    norm2(acc, act);
    fc3_widen(act);
    fc3(act, logits);
    PROF_STAGE(7);
    uint32_t best = 0;
    for (uint32_t i = 1; i < 10; i++) if (logits[i] > logits[best]) best = i;
    return best;
}
